export const PATTERN_CUE: Record<string, string> = {
  "Two Pointers": "Sorted array & you need a pair/triplet, or an in-place partition/dedupe.",
  "Sliding Window": "Longest/shortest/max/min CONTIGUOUS subarray or substring satisfying a condition.",
  "Fast & Slow Pointers": "Detect a cycle, find where a loop starts, or find the middle without a length.",
  "Prefix Sum": "Many range-sum queries, or subarray-sum-to-K when negatives rule out sliding window.",
  "Hashing / Hash Map": "O(1) lookup, complement search, counting, grouping, or dedupe.",
  "Stack": "Next greater/smaller element, matching/nested structure, or histogram spans.",
  "Binary Search": "Sorted input needing O(log n), OR minimize-the-max with a monotonic predicate.",
  "Linked List": "Reverse, merge, or restructure nodes in place (use a dummy node).",
  "Trees – DFS": "Compute something at each node FROM its children (heights, paths, validity).",
  "Trees – BFS": "Process the tree level by level, or shortest path in an unweighted structure.",
  "Heap / Priority Queue": "k largest/smallest/closest, running median, or merge k sorted streams.",
  "Graphs – Traversal": "Grid/graph connectivity (islands/regions), or spreading from source cells (BFS).",
  "Graphs – Topological Sort": "Dependency ordering on a DAG: can finish, build order, prerequisites.",
  "Graphs – Union-Find": "Dynamic connectivity, cycle in undirected graph, or grouping/merging sets.",
  "Graphs – Shortest Path": "Weighted shortest path (Dijkstra / Bellman-Ford).",
  "Backtracking": "Return ALL subsets / permutations / combinations — explore choices, undo each.",
  "Dynamic Programming – 1D": "Min/max/COUNT over choices at each index; scalar answer; overlapping subproblems.",
  "Dynamic Programming – 2D": "Two indices/strings aligned, or grid path count/cost.",
  "Greedy": "A locally-best choice is provably globally optimal; often sort then sweep.",
  "Intervals": "Merge / insert / detect overlaps — sort by start (or end) first.",
  "Bit Manipulation": "XOR tricks, bit counting, or O(1) space using the bits of the values.",
  "Matrix / Simulation": "Traverse or transform a 2D grid in place (spiral, rotate, mark).",
  "Trie": "Prefix search / dictionary of words / autocomplete.",
  "Math & Number Theory": "Digits, primes, overflow, bases — no data structure, just careful math and overflow checks.",
  "Geometry & Spatial": "Rectangles, points, overlap/containment, sweep lines — your Skia hit-testing & bounding-box world.",
  "Strings & Parsing": "Tokenize, convert, and rebuild strings carefully; substring matching via KMP / rolling hash.",
  "Design & OOD": "Implement a small API cleanly — iterators, counters, boards. State + invariants, O(1) ops (Amazon favorite).",
  "Segment Tree & Fenwick": "Point updates + range queries in O(log n); counting inversions while sorting.",
  "Cyclic Sort": "Values are 1..n — the index IS the hash: swap each number into its home slot, then scan.",
  "Randomized & Sampling": "Pick uniformly under constraints: prefix+binary search, reservoir sampling, Fisher-Yates, rejection.",
  "Sorting": "The sorts themselves: custom comparators, counting sort, partitioning tricks, list sorts.",
  "Concurrency (Threads)": "Coordinate threads with semaphores/locks — the print-in-order family (PayPal / systems roles).",
  "Divide & Conquer": "Split, solve halves, combine — when the merge/combine step is the whole insight.",
};

